//! Shared vectors for LUD-05 linking-key derivation: generated by replaying
//! the Breez SDK implementation (`breez-sdk/common/src/lnurl/auth.rs`
//! `get_derivation_path` + `breez-sdk/core/src/signer` `hmac_sha256` and
//! `lnurl_auth.rs` `sign_ecdsa`) with rust-bitcoin, consumed byte-for-byte by
//! the TypeScript signer (`signer/lnurl-auth.ts`).
//!
//! `SPARK_WRITE_VECTORS=1 cargo test --test lnurl_auth` regenerates
//! `vectors/lnurl-auth.json`; otherwise the test asserts the stored file is
//! identical to what the pinned reference produces.

#![allow(
    unused_crate_dependencies,
    clippy::tests_outside_test_module,
    clippy::unwrap_used,
    clippy::expect_used,
    clippy::indexing_slicing,
    clippy::missing_panics_doc,
    clippy::cast_lossless,
    reason = "test code"
)]

use std::path::{Path, PathBuf};

use bitcoin::Network;
use bitcoin::bip32::{ChildNumber, Xpriv};
use bitcoin::hashes::{Hash, HashEngine, Hmac, HmacEngine, sha256};
use bitcoin::key::Secp256k1;
use bitcoin::secp256k1::{All, Message, PublicKey};
use serde_json::{Value, json};

fn vectors_dir() -> PathBuf {
    Path::new(env!("CARGO_MANIFEST_DIR"))
        .join("../../vectors")
        .canonicalize()
        .unwrap()
}

fn write_or_check(name: &str, document: &Value) {
    let path = vectors_dir().join(name);
    if std::env::var_os("SPARK_WRITE_VECTORS").is_some() {
        std::fs::write(
            &path,
            serde_json::to_string_pretty(&document).unwrap() + "\n",
        )
        .unwrap();
        return;
    }
    let stored: Value = serde_json::from_str(&std::fs::read_to_string(&path).unwrap()).unwrap();
    assert_eq!(
        &stored, document,
        "{name} differs; regenerate with SPARK_WRITE_VECTORS=1"
    );
}

const BREEZ_REV: &str = "956ff90b44bed9da9a559372ed3cf1fefe06b8a8";

/// The LUD-04 example challenge: `hex(32 bytes of random data)`.
const K1: &str = "e2af6254a8df433264fa23f67eb8188635d15ce883e8fc020989d5f82ae6f11e";

/// LUD-05: hashing key = m/138'/0; linking key = m/138'/l1/l2/l3/l4 where the
/// elements are four big-endian u32s of HMAC-SHA256(hashingPrivKey, domain)
/// bytes 0..16. u32 elements >= 2^31 derive hardened children, matching
/// `ChildNumber::from(u32)`.
fn hashing_key(secp: &Secp256k1<All>, master: &Xpriv) -> Vec<u8> {
    let hashing = master
        .derive_priv(secp, &[ChildNumber::from_hardened_idx(138).unwrap()])
        .unwrap()
        .derive_priv(secp, &[ChildNumber::from(0)])
        .unwrap();
    hashing.private_key.secret_bytes().to_vec()
}

fn domain_hmac(hashing_priv: &[u8; 32], domain: &str) -> [u8; 32] {
    let mut engine = HmacEngine::<sha256::Hash>::new(hashing_priv);
    engine.input(domain.as_bytes());
    *Hmac::<sha256::Hash>::from_engine(engine).as_byte_array()
}

fn path_elements(mac: &[u8; 32]) -> [u32; 4] {
    let mut out = [0u32; 4];
    for (i, e) in out.iter_mut().enumerate() {
        *e = u32::from_be_bytes(mac[i * 4..i * 4 + 4].try_into().unwrap());
    }
    out
}

fn linking_key(secp: &Secp256k1<All>, master: &Xpriv, elements: &[u32; 4]) -> Xpriv {
    let mut path = vec![ChildNumber::from_hardened_idx(138).unwrap()];
    path.extend(elements.iter().map(|&e| ChildNumber::from(e)));
    master.derive_priv(secp, &path).unwrap()
}

/// The LUD-05 spec vector: hashing key 0x7d41… + domain "site.com" must hash
/// to the documented path suffix (which contains hardened elements).
#[test]
fn lud05_spec_suffix() {
    let hashing_priv =
        hex::decode("7d417a6a5e9a6a4a879aeaba11a11838764c8fa2b959c242d43dea682b3e409b").unwrap();
    let mac = domain_hmac(hashing_priv.as_slice().try_into().unwrap(), "site.com");
    let elements = path_elements(&mac);
    assert_eq!(
        elements,
        [1_588_488_367, 2_659_270_754, 38_110_259, 4_136_336_762],
        "LUD-05 spec vector mismatch"
    );
}

#[test]
fn vectors_lnurl_auth() {
    // BIP-39 "abandon … about" seed plus two fixed seeds; three domains cover
    // a clearnet FQDN, an IDN-free subdomain (also fed uppercased — the caller
    // lowercases before hashing) and a .onion service host.
    let seeds = [
        "5eb00bbddcf069084889a8ab9155568165f5c453ccb85e70811aaed6f6da5fc19a5ac40b389cd370d086206dec8aa6c43daea6690f20ad3d8d48b2d2ce9e38e4",
        "000102030405060708090a0b0c0d0e0f101112131415161718191a1b1c1d1e1f202122232425262728292a2b2c2d2e2f30",
        "fdfbf9f7f5f3f1efedebe9e7e5e3e1dfddd9d7d5d3d1cfcfcdcdcbc9c7c5c3c1bfbdbbb9b7b5b3b1afadaba9a7a5a3a1",
    ];
    let domains: [(&str, Option<&str>); 3] = [
        ("site.com", Some("Site.COM")),
        ("auth.example.com", None),
        ("k1r3v4t9z2x5c8mnbv7qwertyu.onion", None),
    ];

    let secp = Secp256k1::new();
    let k1: [u8; 32] = hex::decode(K1).unwrap().try_into().unwrap();
    let mut cases = Vec::new();
    for seed_hex in seeds {
        let seed = hex::decode(seed_hex).unwrap();
        let master = Xpriv::new_master(Network::Bitcoin, &seed).unwrap();
        let root = master
            .derive_priv(&secp, &[ChildNumber::from_hardened_idx(138).unwrap()])
            .unwrap();
        let mut root_key = root.private_key.secret_bytes().to_vec();
        root_key.extend_from_slice(&root.chain_code[..]);
        let hashing = hashing_key(&secp, &master);

        for &(domain, input) in &domains {
            let mac = domain_hmac(hashing.as_slice().try_into().unwrap(), domain);
            let elements = path_elements(&mac);
            let linking = linking_key(&secp, &master, &elements);
            let public_key = PublicKey::from_secret_key(&secp, &linking.private_key);
            let signature = secp
                .sign_ecdsa(&Message::from_digest(k1), &linking.private_key)
                .serialize_der();
            let mut case = json!({
                "seed": seed_hex,
                "domain": domain,
                "k1": K1,
                "rootKey": hex_str(&root_key),
                "hashingKey": hex_str(&hashing),
                "hmac": hex_str(&mac),
                "path": elements,
                "linkingKey": public_key.to_string(),
                "signature": hex_str(signature.as_ref()),
            });
            if let Some(input) = input {
                case["domainInput"] = json!(input);
            }
            cases.push(case);
        }
    }

    let document = json!({
        "source": format!("breez-spark-sdk crates/breez-sdk/common/src/lnurl/auth.rs + core/src/signer (LUD-04/LUD-05) @ breez-spark-sdk@{BREEZ_REV}"),
        "note": "Test vectors only. Never use these keys for funds.",
        "cases": cases,
    });
    write_or_check("lnurl-auth.json", &document);
}

fn hex_str(bytes: &[u8]) -> String {
    hex::encode(bytes)
}
